package br.com.sysanimais.api

import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.jupiter.api.*
import org.junit.jupiter.api.Assertions.*
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.http.MediaType
import org.springframework.jdbc.core.JdbcTemplate
import org.springframework.security.oauth2.jwt.*
import org.springframework.security.oauth2.jose.jws.MacAlgorithm
import org.springframework.test.context.TestPropertySource
import org.springframework.test.web.servlet.*
import org.springframework.transaction.annotation.Transactional
import java.time.Instant

@SpringBootTest @AutoConfigureMockMvc @Transactional
@TestPropertySource(properties=["spring.datasource.url=jdbc:h2:mem:prontuarios;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","app.jwt-secret=0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"])
class ProntuarioApiTests @Autowired constructor(val mvc:MockMvc,val db:JdbcTemplate,val json:ObjectMapper,val jwt:JwtEncoder,val service:br.com.sysanimais.api.prontuarios.service.ProntuarioService) {
 @jakarta.persistence.PersistenceContext lateinit var em:jakarta.persistence.EntityManager
 private val base="/api/ong/animais/801/prontuarios"
 private val adopted="/api/me/animais-adotados/801/prontuarios"
 @BeforeEach fun fixtures(){
  db.update("INSERT INTO ong(id,nome,email) VALUES(801,'ONG A','a@medical.invalid'),(802,'ONG B','b@medical.invalid')")
  for((id,ong,role) in listOf(Triple(801,801,"administrador"),Triple(802,802,"administrador"),Triple(803,null,"usuario"),Triple(804,null,"usuario"),Triple(805,801,"voluntario"),Triple(806,801,"veterinario"),Triple(807,null,"admin_plataforma")))
   db.update("INSERT INTO usuario(id,ong_id,nome,email,senha_hash,perfil,ativo) VALUES(?,?,?,?,?,?,true)",id,ong,"Pessoa $id","u$id@medical.invalid","x",role)
  for((id,ong) in listOf(801 to 801,802 to 802,803 to 801)) db.update("INSERT INTO animal(id,ong_id,nome,especie,sexo,porte,data_entrada,situacao,situacao_atualizada_em,situacao_alterada_por,ativo,publicado,criado_em,atualizado_em,versao) VALUES(?,?,'Luna','CAO','FEMEA','MEDIO',CURRENT_DATE,'DISPONIVEL',CURRENT_TIMESTAMP,801,true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0)",id,ong)
 }
 private fun auth(id:Int):String {val now=Instant.now();return "Bearer "+jwt.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),JwtClaimsSet.builder().subject(id.toString()).issuedAt(now).expiresAt(now.plusSeconds(3600)).build())).tokenValue}
 private fun body(type:String="CONSULTA")="""{"tipo":"$type","titulo":"Original","descricao":"Avaliação clínica","dataProcedimento":"2020-01-01","profissionalResponsavel":"Dra. Ana","medicamentos":"A","observacoes":"B"}"""
 private fun post(path:String=base,b:String=body(),u:Int=806)=mvc.post(path){header("Authorization",auth(u));contentType=MediaType.APPLICATION_JSON;content=b}
 private fun get(path:String=base,u:Int=806)=mvc.get(path){header("Authorization",auth(u))}
 private fun patch(id:Long,b:String,u:Int=806,path:String=base)=mvc.patch("$path/$id/corrigir"){header("Authorization",auth(u));contentType=MediaType.APPLICATION_JSON;content=b}
 private fun create(type:String="CONSULTA",u:Int=806):Long {val r=post(b=body(type),u=u).andExpect{status{isCreated()};jsonPath("$.registradoPor.id"){value(u)};jsonPath("$.versao"){value(0)}}.andReturn();return json.readTree(r.response.contentAsString)["id"].asLong()}
 @Test fun `seis tipos e dois tipos adicionais reais preservam campos e ator`(){for(t in listOf("CONSULTA","VACINA","EXAME","CIRURGIA","MEDICACAO","VERMIFUGACAO","TRATAMENTO","OBSERVACAO")){val id=create(t);get("$base/$id").andExpect{jsonPath("$.tipo"){value(t)};jsonPath("$.profissionalResponsavel"){value("Dra. Ana")};jsonPath("$.registradoPor.email"){doesNotExist()}}};create(u=801);assertEquals(9,db.queryForObject("SELECT COUNT(*) FROM prontuario",Int::class.java))}
 @Test fun `entrada invalida e campos internos rejeitados`(){for(change in listOf("\"tipo\":\"OUTRO\"","\"titulo\":\" \"","\"descricao\":null","\"dataProcedimento\":\"2999-01-01\"","\"dataProcedimento\":\"2020-02-30\"","\"dataProcedimento\":\"2020-1-1\"","\"titulo\":23","\"titulo\":\"${"a".repeat(121)}\"")){val n=json.readTree(body()).deepCopy<com.fasterxml.jackson.databind.node.ObjectNode>();val pair=json.readTree("{$change}");n.setAll<com.fasterxml.jackson.databind.node.ObjectNode>(pair as com.fasterxml.jackson.databind.node.ObjectNode);post(b=n.toString()).andExpect{status{isBadRequest()}}};for(f in listOf("ongId","animalId","registradoPor","versao"))post(b=body().dropLast(1)+",\"$f\":802}").andExpect{status{isBadRequest()}};post(b="{}").andExpect{status{isBadRequest()}}}
 @Test fun `perfis e autenticacao respeitam policies`(){mvc.get(base).andExpect{status{isUnauthorized()}};for(u in listOf(803,804,807)){get(u=u).andExpect{status{isForbidden()}};post(u=u).andExpect{status{isForbidden()}}};val id=create(u=801);get(u=805).andExpect{status{isOk()}};get("$base/$id/correcoes",805).andExpect{status{isOk()}};post(u=805).andExpect{status{isForbidden()}};patch(id,"""{"titulo":"Novo","justificativa":"Revisão","versao":0}""",805).andExpect{status{isForbidden()}}}
 @Test fun `ong e animal distintos nao vazam detalhes ou correcoes`(){val id=create();for(p in listOf(base,"$base/$id","$base/$id/correcoes"))get(p,802).andExpect{status{isNotFound()}};post(u=802).andExpect{status{isNotFound()}};patch(id,"""{"titulo":"Novo","justificativa":"Revisão","versao":0}""",802).andExpect{status{isNotFound()}};get("/api/ong/animais/803/prontuarios/$id").andExpect{status{isNotFound()}};get("$base/999999").andExpect{status{isNotFound()}}}
 @Test fun `filtros ordem paginacao e periodo estritos`(){create();create("VACINA");get("$base?size=1&page=1").andExpect{status{isOk()};jsonPath("$.number"){value(1)};jsonPath("$.totalElements"){value(2)};jsonPath("$.content[0].tipo"){value("CONSULTA")}};get("$base?tipo=VACINA&de=2020-01-01&ate=2020-01-01").andExpect{jsonPath("$.totalElements"){value(1)}};for(q in listOf("page=-1","size=101","tipo=OUTRO","de=2020-02-30","de=2021-01-01&ate=2020-01-01"))get("$base?$q").andExpect{status{isBadRequest()}}}
 @Test fun `adotado e falecido preservam leitura e correcao sem novos procedimentos`(){val id=create();for(state in listOf("ADOTADO","FALECIDO")){em.flush();em.clear();db.update("UPDATE animal SET situacao=? WHERE id=801",state);post().andExpect{status{isConflict()}};get("$base/$id").andExpect{status{isOk()}}};patch(id,"""{"titulo":"Revisado","justificativa":"Revisão póstuma","versao":0}""").andExpect{status{isOk()}}}
 @Test fun `inativo e reservado ainda admitem registros`(){for(s in listOf("EM_TRATAMENTO","EM_PROCESSO_ADOCAO")){em.clear();db.update("UPDATE animal SET situacao=?,ativo=false WHERE id=801",s);create()}}
 @Test fun `correcoes parciais preservam autor snapshots nulos e ordem`(){val id=create(u=801);patch(id,"""{"titulo":"Revisado","observacoes":null,"justificativa":"Revisão clínica","versao":0}""").andExpect{status{isOk()};jsonPath("$.versao"){value(1)};jsonPath("$.registradoPor.id"){value(801)};jsonPath("$.observacoes"){doesNotExist()}};patch(id,"""{"descricao":"Nova descrição","justificativa":"Complemento","versao":1}""").andExpect{status{isOk()};jsonPath("$.versao"){value(2)}};get("$base/$id/correcoes?size=1&page=0",805).andExpect{status{isOk()};jsonPath("$.totalElements"){value(2)};jsonPath("$.content[0].dadosAnteriores.titulo"){value("Original")};jsonPath("$.content[0].dadosNovos.titulo"){value("Revisado")};jsonPath("$.content[0].corrigidoPor.id"){value(806)}};get("$base/$id/correcoes?page=1&size=1").andExpect{jsonPath("$.content[0].dadosAnteriores.titulo"){value("Revisado")};jsonPath("$.content[0].dadosNovos.descricao"){value("Nova descrição")}}}
 @Test fun `correcao exige justificativa versao e mudanca clinica valida`(){val id=create();for(b in listOf("""{"titulo":"Novo","versao":0}""","""{"titulo":"Novo","justificativa":" ","versao":0}""","""{"titulo":"Novo","justificativa":"Revisão"}""","""{"justificativa":"Revisão","versao":0}""","""{"titulo":"Original","justificativa":"Revisão","versao":0}""","""{"tipo":null,"justificativa":"Revisão","versao":0}""","""{"dataProcedimento":"2999-01-01","justificativa":"Revisão","versao":0}""","""{"animalId":802,"justificativa":"Revisão","versao":0}""","""{"titulo":"Novo","justificativa":"Revisão","versao":"0"}"""))patch(id,b).andExpect{status{isBadRequest()}};assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM correcao_prontuario",Int::class.java))}
 @Test fun `versao desatualizada nao sobrescreve nem gera historico`(){val id=create();patch(id,"""{"titulo":"Versão nova","justificativa":"Revisão","versao":0}""").andExpect{status{isOk()}};patch(id,"""{"titulo":"Sobrescrita","justificativa":"Revisão antiga","versao":0}""").andExpect{status{isConflict()}};get("$base/$id").andExpect{jsonPath("$.titulo"){value("Versão nova")}};assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM correcao_prontuario",Int::class.java))}
 @Test fun `adotante so le apos entrega e sem dados de auditoria`(){val id=create();get(adopted,803).andExpect{status{isNotFound()}};val r=post("/api/adoption-requests","""{"animalId":801}""",803).andExpect{status{isCreated()}}.andReturn();val requestId=json.readTree(r.response.contentAsString)["id"].asLong();mvc.patch("/api/ong/adoption-requests/$requestId/aprovar"){header("Authorization",auth(801))}.andExpect{status{isOk()}};get(adopted,803).andExpect{status{isNotFound()}};mvc.post("/api/ong/adoption-requests/$requestId/confirmar-entrega"){header("Authorization",auth(801));contentType=MediaType.APPLICATION_JSON;content="""{"entregaConfirmada":true}"""}.andExpect{status{isOk()}};get(adopted,803).andExpect{status{isOk()};jsonPath("$.totalElements"){value(1)}};get("$adopted/$id",803).andExpect{status{isOk()};jsonPath("$.titulo"){value("Original")};jsonPath("$.registradoPor"){doesNotExist()};jsonPath("$.ongId"){doesNotExist()};jsonPath("$.versao"){doesNotExist()}};get(adopted,804).andExpect{status{isNotFound()}};get("$adopted/99999",803).andExpect{status{isNotFound()}};get("/api/me/animais-adotados/803/prontuarios",803).andExpect{status{isNotFound()}};get(adopted,801).andExpect{status{isForbidden()}};post(adopted,body(),803).andExpect{status{isForbidden()}};patch(id,"{}",803,adopted).andExpect{status{isForbidden()}};get("$adopted/$id/correcoes",803).andExpect{status{isForbidden()}};em.flush();em.clear();db.update("UPDATE ong SET situacao='SUSPENSA' WHERE id=801");get(adopted,803).andExpect{status{isOk()}}}
 @Test fun `contas inativas ong suspensa e token revogado impedem acesso`(){create();for(sql in listOf("UPDATE usuario SET ativo=false WHERE id=806","UPDATE usuario SET token_versao=1 WHERE id=806")){em.flush();em.clear();db.update(sql);get().andExpect{status{isForbidden()}};db.update("UPDATE usuario SET ativo=true,token_versao=0 WHERE id=806");em.clear()};db.update("UPDATE ong SET situacao='SUSPENSA' WHERE id=801");em.clear();get().andExpect{status{isForbidden()}}}
 @Test fun `nenhuma rota comum de edicao exclusao ou consulta publica`(){val id=create();mvc.delete("$base/$id"){header("Authorization",auth(801))}.andExpect{status{isForbidden()}};mvc.patch("$base/$id"){header("Authorization",auth(801));contentType=MediaType.APPLICATION_JSON;content="{}"}.andExpect{status{isForbidden()}};mvc.get("/api/animais/801/prontuarios").andExpect{status{isUnauthorized()}}}
 @Test fun `chave composta impede associacao fisica entre animal e outra ong`(){val id=create();em.flush();assertThrows(org.springframework.dao.DataIntegrityViolationException::class.java){db.update("UPDATE prontuario SET ong_id=802 WHERE id=?",id)}}

 // H2 VARCHAR counts UTF-16; the MySQL script separately verifies real persistence of 120 emoji.
 @Test fun `limites unicode contam caracteres e nao unidades utf16`(){val n=json.readTree(body()) as com.fasterxml.jackson.databind.node.ObjectNode;n.put("titulo","🐾".repeat(120));assertEquals("🐾".repeat(120),service.validateClinicalData(n.properties().associate{it.key to it.value}).titulo);n.put("titulo","🐾".repeat(121));post(b=n.toString()).andExpect{status{isBadRequest()}}}
 @Test fun `offset fora do limite jpa retorna erro de entrada`(){get("$base?page=2147483647&size=100").andExpect{status{isBadRequest()}}}

}
